def approaches(inp):
    H,W=len(inp),len(inp[0])
    (r1,c1)=min((r,c) for r in range(H) for c in range(W) if inp[r][c]==1)
    (r2,c2)=min((r,c) for r in range(H) for c in range(W) if inp[r][c]==2)
    # diagonals through 1
    D1=[lambda r,c:r+c==r1+c1, lambda r,c:r-c==r1-c1]
    res=[]
    # vertical approach from 2: col fixed = c2, moving toward 1's row side
    for name,dr in (('down',1),('up',-1)):
        rng=range(r2+dr,r1+dr) if dr>0 else list(range(r2+dr,r1+dr))[::-1]
        inter=None
        for r in rng:
            c=c2
            if 0<=c<W and any(Dj(r,c) for Dj in D1):
                inter=(r,c)
        if inter and 0<=inter[0]<H and 0<=inter[1]<W:
            cells={(r,c2) for r in range(min(r2,inter[0]),max(r2,inter[0])+1) if (r,c2)!=(r2,c2)}
            # plus diag from inter toward 1
            dd = 1 if r1>inter[0] else -1
            dc_ = 1 if c1>inter[1] else -1
            cur=inter
            while True:
                cur=(cur[0]+dd,cur[1]+dc_)
                if cur==(r1,c1) or abs(cur[0]-r1)==1 and abs(cur[1]-c1)==1: break
                if 0<=cur[0]<H and 0<=cur[1]<W: cells.add(cur)
            res.append(('vert',dr,len(cells),sorted(cells)))
    # horizontal approach from 2: row fixed=r2
    for name,dc in (('right',1),('left',-1)):
        rng=range(c2+dc,c1+dc) if dc>0 else list(range(c2+dc,c1+dc))[::-1]
        inter=None
        for c in rng:
            r=r2
            if 0<=r<H and any(Dj(r,c) for Dj in D1):
                inter=(r,c)
        if inter and 0<=inter[0]<H and 0<=inter[1]<W:
            cells={(r2,c) for c in range(min(c2,inter[1]),max(c2,inter[1])+1) if (r2,c)!=(r2,c2)}
            dd = 1 if r1>r2 else -1
            dc_ = 1 if c1>inter[1] else -1
            cur=inter
            while True:
                cur=(cur[0]+dd,cur[1]+dc_)
                if cur==(r1,c1) or abs(cur[0]-r1)<=1 and abs(cur[1]-c1)<=1: break
                if 0<=cur[0]<H and 0<=cur[1]<W: cells.add(cur)
            res.append(('horiz',dc,len(cells),sorted(cells)))
    return res
