def f(inp):
    H,W=len(inp),len(inp[0])
    (r1,c1)=min((r,c) for r in range(H) for c in range(W) if inp[r][c]==1)
    (r2,c2)=min((r,c) for r in range(H) for c in range(W) if inp[r][c]==2)
    o=[row[:] for row in inp]
    vert = abs(r1-r2)>=abs(c1-c2)
    diagmain = (r1-c1==(r2-c2)) if False else None
    d1,r1d=c1-r2, r1-r2
    # diagonal slopes: slope +1 (r-c const) or -1 (r+c const) through 1
    def on_diag(r,c,main): return (r-c==r1-c1) if main else (r+c==r1+c1)
    if vert:
        col = c2+(1 if c1>c2 else -1)
        s = 1 if r1>r2 else -1   # toward 1 vertically
        run=[]; cur=r2+s
        while 0<=cur<H:
            if on_diag(cur,col,True):  # hit main-diag (slope +1)
                inter=cur; break
            if on_diag(cur,col,False):# hit anti-diag (slope -1)
                inter=cur; break
            run.append(cur); cur+=s
        else:
            inter=None
        for r in run+[inter]:
            if 0<=r<H: o[r][col]=3
        if inter is not None:
            ns = s; nc = -1 if c1<col else 1
            cur=(inter, col)
            while True:
                nxt=(cur[0]+ns, cur[1]+nc)
                if not(0<=nxt[0]<H and 0<=nxt[1]<W) or nxt==(r1,c1): break
                o[nxt[0]][nxt[1]]=3
                cur=nxt
    else:
        row = r2+(1 if r1>r2 else -1)
        s = 1 if c1>c2 else -1
        run=[]; cur=c2+s
        while 0<=cur<W:
            if on_diag(row,cur,True) or on_diag(row,cur,False):
                inter=cur; break
            run.append(cur); cur+=s
        else:
            inter=None
        for c in run+[inter]:
            if 0<=c<W: o[row][c]=3
        if inter is not None:
            ns = s; nr = -1 if r1<row else 1
            cur=(row, inter)
            while True:
                nxt=(cur[0]+nr, cur[1]+ns)
                if not(0<=nxt[0]<H and 0<=nxt[1]<W) or nxt==(r1,c1): break
                o[nxt[0]][nxt[1]]=3
                cur=nxt
    return o
